import { escapeHtml as e } from './operations-page.ts';
import type { ConnectView } from './direct-connect.ts';
export function renderDirectConnect(view?: ConnectView) {
  const names: Record<string,string>={connected:'Кабинет подключён',disconnected:'Директ не подключён',expired:'Срок доступа истёк',invalid:'Токен больше не действует — подключите кабинет заново',access_denied:'Доступ к API или право изменения не подтверждены',configuration_changed:'Конфигурация приложения изменилась — подключите кабинет заново'};
  if(!view)return '<section class="direct-panel"><h1>Подключение Директа</h1><p>Администратор ещё не настроил подключение. Подготовку можно сохранить.</p><a href="/">Вернуться к плану</a></section>';
  return `<section class="direct-panel" aria-labelledby="connect-title"><h1 id="connect-title">Свой кабинет Директа</h1><p class="source-note">${view.mode==='fixture'?'Подставной API · отдельная проверочная база':'Настоящий API Яндекса'}</p>
  <p>Сейчас поддерживается собственный кабинет прямого рекламодателя в рублях от имени главного представителя. Вход в сервис и разрешение Директа — отдельные действия.</p><h2>${e(names[view.status]??'Проверьте подключение')}</h2>
  ${view.account?`<p>Кабинет <code>${e(view.account)}</code>${view.login?` · главный представитель ${e(view.login)}`:''}</p>`:''}
  ${view.checkedAt?`<p>Последняя успешная проверка: ${e(new Date(view.checkedAt).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}))} МСК. Это не проверка текущих прав в реальном времени.</p>`:''}
  ${view.attempt?`<h2>1. Разрешите доступ у Яндекса</h2><p><a class="button secondary" href="${e(view.attempt.url)}" target="_blank" rel="noopener noreferrer">Открыть Яндекс и получить код</a></p><p>Вернитесь сюда и введите одноразовый код. Токен копировать не нужно. Попытка действует 10 минут.</p><h2>2. Введите код</h2><form method="post" action="/connections/direct/finish"><input type="hidden" name="attemptId" value="${e(view.attempt.id)}"><input type="hidden" name="nonce" value="${e(view.attempt.nonce)}"><div class="field"><label for="direct-code">Одноразовый код Яндекса</label><input id="direct-code" name="code" autocomplete="one-time-code" maxlength="1024" required></div><button class="primary" type="submit">Проверить мой кабинет</button></form><form method="post" action="/connections/direct/cancel"><button class="secondary" type="submit">Отменить подключение</button></form>`:''}
  ${view.candidate?`<h2>Подтвердите свой кабинет</h2><p>Главный представитель ${e(view.candidate.login)} · кабинет <code>${e(view.candidate.account)}</code> · RUB · создание ЕПК разрешено.</p><form method="post" action="/connections/direct/activate"><input type="hidden" name="candidateId" value="${e(view.candidate.id)}"><label class="check"><input type="checkbox" name="confirm" value="yes" required>Это мой кабинет. Подтверждаю выбор. Подключение не создаёт рекламу.</label><button class="primary" type="submit">Подключить этот кабинет</button></form><form method="post" action="/connections/direct/cancel"><button class="secondary" type="submit">Отменить подключение</button></form>`:''}
  <form method="post" action="/connections/direct/start"><button class="secondary" type="submit">${view.status==='connected'?'Подключить заново / выбрать свой кабинет':'Подключить свой Директ'}</button></form>
  <form method="post" action="/connections/direct/disconnect"><button class="secondary" type="submit">Отключить доступ</button><p class="hint">История останется. Уже отправленный запрос может завершиться; новые запросы после отключения не отправляются.</p></form>
  <p><a href="https://id.yandex.ru/security/permissions" target="_blank" rel="noopener noreferrer">Отозвать разрешение у Яндекса</a>. Отключение в сервисе удаляет наш доступ, но не отзывает само разрешение у Яндекса.</p><p><a href="/">Вернуться к плану</a> · <a href="/history#direct-history">История операций</a></p></section>`;
}
